@startuml

class MasterCourse {
  + Name : string
}

class Edition {
  + ParticipantsCount : int
}

class Lesson {
  + Date : date
  + StartTime : time
  + Duration : int
  + Room : string
}

class Resource {
  + Name : string
}

class Teacher {
  + Name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {
  + Name : string
}

class ExternalAuditor {
  + Name : string
}

MasterCourse "1" -- "0..*" Edition
Edition "1" *-- "1..*" Lesson
Lesson "0..*" -- "1..*" Teacher
MasterCourse "0..*" -- "0..*" Teacher : preallocated
MasterCourse "1" -- "1" InternalTeacher : responsible

Edition "1" -- "0..*" MasterStudent : enrolled
Edition "1" -- "0..*" ExternalAuditor : enrolled

Lesson "0..*" -- "0..*" Resource : requires

@enduml

